const jg='http://disclosure.edinet-fsa.go.jp/taxonomy/jppfs/2025-11-01/jppfs_cor',dei='http://disclosure.edinet-fsa.go.jp/taxonomy/jpdei/2013-08-31/jpdei_cor',ifrs='http://disclosure.edinet-fsa.go.jp/taxonomy/jpigp/2025-11-01/jpigp_cor';
export function reportingInstance(options:{standard?:string;consolidated?:string;periodCode?:string;form?:string;start?:string;end?:string;currentEnd?:string;filing?:string;issuer?:string;entity?:string;security?:string|null;omit?:string;duplicate?:string;extra?:string;currency?:string;durationId?:string;durationStart?:string;noDuration?:boolean;noInstant?:boolean;deiNamespace?:string;duplicateDuration?:boolean}={}){
 const {standard='Japan GAAP',consolidated='true',periodCode='FY',form=periodCode==='FY'?'第三号様式':'第四号の三様式',start='2025-04-01',end='2026-03-31',currentEnd=end,filing='2026-06-24',issuer='E12345',entity=issuer+'-000',security='10010',currency='JPY',durationId='arbitrary-duration'}=options;
 const dimension=consolidated==='false'||consolidated==='0'?'<xbrli:scenario><xbrldi:explicitMember dimension="jppfs_cor:ConsolidatedOrNonConsolidatedAxis">jppfs_cor:NonConsolidatedMember</xbrldi:explicitMember></xbrli:scenario>':'';
 const context=(id:string,period:string,dim='')=>'<xbrli:context id="'+id+'"><xbrli:entity><xbrli:identifier scheme="http://disclosure.edinet-fsa.go.jp">'+entity+'</xbrli:identifier></xbrli:entity><xbrli:period>'+period+'</xbrli:period>'+dim+'</xbrli:context>';
 const duration=context(durationId,'<xbrli:startDate>'+(options.durationStart??start)+'</xbrli:startDate><xbrli:endDate>'+currentEnd+'</xbrli:endDate>',dimension),instant=context('arbitrary-instant','<xbrli:instant>'+currentEnd+'</xbrli:instant>',dimension);
 const values:Record<string,string|null>={EDINETCodeDEI:issuer,SecurityCodeDEI:security,DocumentTypeDEI:form,AccountingStandardsDEI:standard,WhetherConsolidatedFinancialStatementsArePreparedDEI:consolidated,CurrentFiscalYearStartDateDEI:start,CurrentFiscalYearEndDateDEI:end,CurrentPeriodEndDateDEI:currentEnd,TypeOfCurrentPeriodDEI:periodCode};
 const facts=Object.entries(values).filter(([tag])=>tag!==options.omit).map(([tag,value])=>{const f='<d:'+tag+' contextRef="filing"'+(value===null?' xsi:nil="true"':'')+'>'+(value??'')+'</d:'+tag+'>';return f+(options.duplicate===tag?f:'');}).join('');
 const fact=(prefix:string,tag:string,value:string,ref:string)=>'<'+prefix+':'+tag+' contextRef="'+ref+'" unitRef="money" decimals="0">'+value+'</'+prefix+':'+tag+'>';
 const money=standard==='IFRS'?['CurrentAssetsIFRS','TotalCurrentLiabilitiesIFRS','LiabilitiesIFRS'].map((tag,i)=>fact('jpigp_cor',tag,String((i+1)*100),'arbitrary-instant')).join('')+['CostOfSalesIFRS','GrossProfitIFRS','SellingGeneralAndAdministrativeExpensesIFRS','ProfitLossBeforeTaxIFRS','IncomeTaxExpenseIFRS'].map((tag,i)=>fact('jpigp_cor',tag,String((i+1)*10),durationId)).join(''):
 ['CurrentAssets','CurrentLiabilities','Liabilities'].map((tag,i)=>fact('jppfs_cor',tag,String((i+1)*100),'arbitrary-instant')).join('')+['CostOfSales','SellingGeneralAndAdministrativeExpenses'].map((tag,i)=>fact('jppfs_cor',tag,String((i+1)*10),durationId)).join('');
 return '<xbrli:xbrl xmlns:xbrli="http://www.xbrl.org/2003/instance" xmlns:xbrldi="http://xbrl.org/2006/xbrldi" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:iso4217="http://www.xbrl.org/2003/iso4217" xmlns:d="'+(options.deiNamespace??dei)+'" xmlns:jppfs_cor="'+jg+'" xmlns:jpigp_cor="'+ifrs+'">'+context('filing','<xbrli:instant>'+filing+'</xbrli:instant>')+(options.noDuration?'':duration+(options.duplicateDuration?duration:''))+(options.noInstant?'':instant)+'<xbrli:unit id="money"><xbrli:measure>iso4217:'+currency+'</xbrli:measure></xbrli:unit>'+facts+money+(options.extra??'')+'</xbrli:xbrl>';
}
